diff --git a/backend/internal/server/merge_gate.go b/backend/internal/server/merge_gate.go
index 3f9a1c2..e04b7d5 100644
--- a/backend/internal/server/merge_gate.go
+++ b/backend/internal/server/merge_gate.go
@@ -88,25 +88,41 @@ func (s *Server) handleMergeRun(w http.ResponseWriter, r *http.Request) {
 	run, ok := s.loadRunForMerge(w, r)
 	if !ok {
 		return
 	}
-	cov, err := s.reviewCoverageFor(r.Context(), run.ID, run.HeadSHA)
-	if err != nil {
-		if errors.Is(err, store.ErrNotFound) {
-			writeError(w, http.StatusConflict, "coverage_missing", "run %s has no review coverage at %s", run.ID, run.HeadSHA)
-			return
-		}
-		writeError(w, http.StatusInternalServerError, "coverage_lookup_failed", "%v", err)
-		return
-	}
-	if !cov.Complete() {
-		writeError(w, http.StatusConflict, "coverage_incomplete", "run %s: %s", run.ID, cov.Missing())
-		return
-	}
+	cov, err := s.lookupCoverage(r.Context(), run)
+	switch {
+	case err == nil:
+		if !cov.Complete() {
+			writeError(w, http.StatusConflict, "coverage_incomplete", "run %s: %s", run.ID, cov.Missing())
+			return
+		}
+	case errors.Is(err, store.ErrNotFound):
+		writeError(w, http.StatusConflict, "coverage_missing", "run %s has no review coverage at %s", run.ID, run.HeadSHA)
+		return
+	case errors.Is(err, context.DeadlineExceeded):
+		s.log.Warn("merge: review coverage lookup timed out after retry", "run", run.ID, "head", run.HeadSHA, "err", err)
+	default:
+		writeError(w, http.StatusInternalServerError, "coverage_lookup_failed", "%v", err)
+		return
+	}
 	if err := s.queueMerge(r.Context(), run); err != nil {
 		writeError(w, http.StatusBadGateway, "merge_queue_failed", "%v", err)
 		return
 	}
 	writeJSON(w, http.StatusAccepted, mergeAccepted{RunID: run.ID})
 }
+
+// lookupCoverage reads the run's review coverage at its head. A read that
+// hits the store deadline is retried once; reviewCoverageFor applies its own
+// 2s deadline per call.
+func (s *Server) lookupCoverage(ctx context.Context, run store.Run) (store.Coverage, error) {
+	cov, err := s.reviewCoverageFor(ctx, run.ID, run.HeadSHA)
+	if !errors.Is(err, context.DeadlineExceeded) {
+		return cov, err
+	}
+	mergeGateLookupRetries.Inc()
+	return s.reviewCoverageFor(ctx, run.ID, run.HeadSHA)
+}
diff --git a/backend/internal/server/metrics.go b/backend/internal/server/metrics.go
index 71c0d3e..5a8e2f6 100644
--- a/backend/internal/server/metrics.go
+++ b/backend/internal/server/metrics.go
@@ -52,6 +52,12 @@ var (
 		Name: "fishhawkd_merge_queue_depth",
 		Help: "Runs waiting in the merge queue.",
 	})
+	// mergeGateLookupRetries counts merge-gate review-coverage reads retried
+	// after a deadline.
+	mergeGateLookupRetries = promauto.NewCounter(prometheus.CounterOpts{
+		Name: "fishhawkd_merge_gate_lookup_retries_total",
+		Help: "Review-coverage reads the merge gate retried after a deadline.",
+	})
 )
