index a81d4c0..2f6b9e3 100644
--- a/backend/internal/server/merge_gate_test.go
+++ b/backend/internal/server/merge_gate_test.go
@@ -140,6 +140,32 @@ func TestHandleMergeRun_CoverageMissing(t *testing.T) {
 	if rec.Code != http.StatusConflict {
 		t.Fatalf("status = %d, want 409", rec.Code)
 	}
 }
+
+func TestHandleMergeRun_CoverageReadRetriedAfterDeadline(t *testing.T) {
+	srv, st := newMergeGateServer(t)
+	st.coverageErrs = []error{context.DeadlineExceeded, nil}
+	st.coverage = completeCoverage()
+	rec := doMerge(t, srv, "run-1")
+	if rec.Code != http.StatusAccepted {
+		t.Fatalf("status = %d, want 202", rec.Code)
+	}
+	if st.coverageCalls != 2 {
+		t.Errorf("coverage reads = %d, want 2", st.coverageCalls)
+	}
+}
+
+func TestHandleMergeRun_CoverageReadError(t *testing.T) {
+	srv, st := newMergeGateServer(t)
+	st.coverageErrs = []error{errors.New("connection reset")}
+	rec := doMerge(t, srv, "run-1")
+	if rec.Code != http.StatusInternalServerError {
+		t.Fatalf("status = %d, want 500", rec.Code)
+	}
+	if st.queued != 0 {
+		t.Errorf("merges queued = %d, want 0", st.queued)
+	}
+}
